variables.input:
timeseries n=count(`snmp.winserver.hr.systemuptime`), by:{`dt.entity.dt:snmp-winserver`, device.name}
| fields device.name
| filter isNotNull(device.name)

2.query:
timeseries load=avg(`snmp.winserver.hr.processorload`), by:{device.name}, filter:{in(device.name, array($ServerName))}
| fieldsAdd c = arrayLast(load)
| summarize `CPU >= 95%` = countIf(c >= 95)

3.query:
timeseries { size=avg(`snmp.winserver.hr.storagesize`), used=avg(`snmp.winserver.hr.storageused`) }, by:{device.name, storage.allocationunits}, filter:{in(device.name, array($ServerName)) AND contains(storage.descr, "Physical Memory")}
| fieldsAdd m = arrayLast(used) / arrayLast(size) * 100
| summarize `Memory >= 95%` = countIf(m >= 95)

6.query:
timeseries { load=avg(`snmp.winserver.hr.processorload`), busy=max(`snmp.winserver.hr.processorload`) }, by:{device.name}, filter:{in(device.name, array($ServerName))}
| fieldsAdd `CPU %` = arrayLast(load), `Busiest core %` = arrayLast(busy)
| fields device.name, `CPU %`, `Busiest core %`
| join [ timeseries { size=avg(`snmp.winserver.hr.storagesize`), used=avg(`snmp.winserver.hr.storageused`) }, by:{device.name, storage.allocationunits}, filter:{in(device.name, array($ServerName)) AND contains(storage.descr, "Physical Memory")} | fieldsAdd `Memory %` = arrayLast(used) / arrayLast(size) * 100 | fields device.name, `Memory %` ], kind:leftOuter, on:{device.name}, fields:{`Memory %`}
| join [ timeseries u=avg(`snmp.winserver.hr.systemuptime`), by:{device.name}, filter:{in(device.name, array($ServerName))} | fieldsAdd `Uptime days` = arrayLast(u) / 8640000 | fields device.name, `Uptime days` ], kind:leftOuter, on:{device.name}, fields:{`Uptime days`}
| join [ timeseries { size=avg(`snmp.winserver.hr.storagesize`), used=avg(`snmp.winserver.hr.storageused`) }, by:{device.name, storage.descr, storage.allocationunits}, filter:{in(device.name, array($ServerName))} | filter substring(storage.descr, from: 1, to: 2) == ":" and arrayLast(size) > 0 | fieldsAdd Disk = substring(storage.descr, from: 0, to: 3), alloc = toDouble(storage.allocationunits) | fieldsAdd p = arrayLast(used) / arrayLast(size) * 100 | summarize `Fullest disk %` = max(p), by:{device.name} ], kind:leftOuter, on:{device.name}, fields:{`Fullest disk %`}
| join [ timeseries st=avg(`snmp.winserver.svc.operatingstate`), by:{device.name, svc.name}, filter:{in(device.name, array($ServerName))} | filter isNotNull(arrayLast(st)) | summarize `Running services` = count(), by:{device.name} ], kind:leftOuter, on:{device.name}, fields:{`Running services`}
| sort `CPU %` desc

10.query:
timeseries { size=avg(`snmp.winserver.hr.storagesize`), used=avg(`snmp.winserver.hr.storageused`) }, by:{device.name, storage.allocationunits}, filter:{in(device.name, array($ServerName)) AND contains(storage.descr, "Physical Memory")}
| fieldsAdd `Memory used %` = used[] / size[] * 100
| fields timeframe, interval, device.name, `Memory used %`

15.query:
timeseries rx=sum(`snmp.winserver.if.in.octets.count`, rate:1s), by:{device.name}, filter:{in(device.name, array($ServerName))}
| fieldsAdd `NIC received Mbit/s` = rx[] * 8 / 1000000
| fieldsRemove rx

16.query:
timeseries { e=sum(`snmp.winserver.if.in.errors.count`), d=sum(`snmp.winserver.if.in.discards.count`) }, by:{device.name}, filter:{in(device.name, array($ServerName))}
| fieldsAdd Errors = e[] , Discards = d[]
| fieldsRemove e, d

17.query:
timeseries st=avg(`snmp.winserver.svc.operatingstate`), by:{device.name, svc.name}, filter:{in(device.name, array($ServerName))}
| filter isNotNull(arrayLast(st))
| summarize `Running services` = count(), by:{device.name}
| sort `Running services` desc
